import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSheetToday, type SheetToday } from './useSheetToday';

/** The sheet's today, shown and changeable, and whether it is archived, with the steward's archive
 *  button and the steward's clone to another (never used) sheet id. Changing today re-reads the whole sheet,
 *  since every date decision in it depends on today. All share the one sheet error: the last of them refused. */
function TodayControl({ sheetId }: { sheetId: string }) {
  const today = useSheetToday(sheetId);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (raw: string) =>
      postJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { date: raw.trim() }),
    onSuccess: (sheet) => {
      queryClient.setQueryData(['sheet', sheetId, 'today'], sheet);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'today',
      });
    },
  });
  const archive = useMutation({
    mutationFn: () => postJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, {}),
    onSuccess: (sheet) => queryClient.setQueryData(['sheet', sheetId, 'today'], sheet),
  });
  const [cloneTo, setCloneTo] = useState('');
  const clone = useMutation({
    mutationFn: (toSheetId: string) =>
      postJson<{ clonedTo: string }>(`/api/sheets/${encodeURIComponent(sheetId)}/clone`, { toSheetId }),
  });
  const error = save.error ?? archive.error ?? clone.error;
  const resetAll = () => {
    save.reset();
    archive.reset();
    clone.reset();
  };

  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          resetAll();
          return save.mutateAsync(date);
        });
      }}
    >
      Today: <strong data-testid="sheet-today">{today.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="sheet-today-input"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            resetAll();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>
      Archived: <strong data-testid="sheet-archived">{today.data ? (today.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() =>
          submitOnce(() => {
            resetAll();
            return archive.mutateAsync();
          })
        }
      >
        Archive sheet
      </button>{' '}
      <label>
        Clone to{' '}
        <input
          type="text"
          placeholder="Sheet id"
          data-testid="sheet-clone-to"
          value={cloneTo}
          onChange={(e) => {
            setCloneTo(e.target.value);
            resetAll();
          }}
        />
      </label>{' '}
      <button
        type="button"
        data-testid="sheet-clone"
        disabled={clone.isPending}
        onClick={() =>
          submitOnce(() => {
            resetAll();
            return clone.mutateAsync(cloneTo);
          })
        }
      >
        Clone sheet
      </button>{' '}
      Cloned to: <strong data-testid="sheet-cloned-to">{clone.data?.clonedTo ?? ''}</strong>
      {error && <p data-testid="sheet-error">{error.message}</p>}
    </form>
  );
}

export const contribution = SheetBody.fill({
  order: 0,
  Component: ({ sheetId }) => <TodayControl sheetId={sheetId} />,
});
import { useQuery } from '@tanstack/react-query';
import { useReader } from '../../api/readNow';

export type SheetToday = { id: string; today: string; archived: boolean };

/** The sheet's today (yyyy-mm-dd), and whether it is archived. Every date decision and default date in a sheet uses this,
 *  never the browser's clock. */
export function useSheetToday(sheetId: string) {
  const read = useReader();
  return useQuery({
    queryKey: read.key(['sheet', sheetId, 'today']),
    queryFn: () => read.get<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`),
  });
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data. The rejection's message is the
// server's own `error` text when it sent one.
//
// Every request carries the signed-in name in X-User (the server records it as `by=<user>`), and,
// while this screen shows the sheet as of a date, that date in X-As-Of: reads answer as the sheet stood
// then, and every change is refused.
let signedInUser = '';
let asOfDate = '';

/** A non-2xx answer: the server's message, and its status (409 when someone else saved first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** Called by the session (features/session) whenever the signed-in name changes. */
export function setSignedInUser(name: string): void {
  signedInUser = name;
}

/** Called by the as-of control (features/asof) whenever the screen's as-of date changes ('' when none). */
export function setAsOfDate(date: string): void {
  asOfDate = date;
}

/** The as-of date requests are sent with ('' when none). */
export function currentAsOfDate(): string {
  return asOfDate;
}

async function send<T>(path: string, init?: RequestInit, asOf = asOfDate): Promise<T> {
  const headers = new Headers(init?.headers);
  if (signedInUser) headers.set('X-User', signedInUser);
  if (asOf) headers.set('X-As-Of', asOf);
  const res = await fetch(path, { ...init, headers });
  if (!res.ok) {
    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
    try {
      const body = (await res.json()) as { error?: string };
      if (body?.error) message = body.error;
    } catch {
      /* no JSON body: keep the status message */
    }
    throw new HttpError(message, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

/** A read that answers as the store holds the sheet now, whatever date this screen shows it as of. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path, undefined, '');
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { createContext, useContext } from 'react';
import { getJson, getJsonNow } from './http';

/** Set to true around components that must show the sheet as the store holds it now while the screen shows it as
 *  of a date: the shared read hooks then answer as of now, under keys of their own. */
export const ReadNow = createContext(false);

/** How a shared read hook reads: its getter, and its query key (suffixed when it reads now under an as-of date). */
export function useReader(): { get: <T>(path: string) => Promise<T>; key: (key: unknown[]) => unknown[] } {
  const now = useContext(ReadNow);
  return now
    ? { get: getJsonNow, key: (key) => [...key, 'read-now'] }
    : { get: getJson, key: (key) => key };
}

